/// completion form on approval. If CSP or a JS-off client blocks it, the no-JS continue button is
/// the fallback — the whole flow still completes.

async fn perform_did_ceremony(
    handle: String,
    password: String,
    state: tauri::State<'_, oauth::AppState>,
) -> Result<DIDCeremonyResult, DIDCeremonyError> {
    let context = load_did_ceremony_context()?;
